import React, { useEffect, useState } from "react";

export default function Schemes(props) {
  const [schemes, setSchemes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchSchemes = async () => {
      try {
        const res = await fetch(props.getEndpoint);
        const data = await res.json();

        if (!res.ok) {
          setError(data.message || "Failed to fetch scholarships");
          return;
        }

        setSchemes(data.scholarships || []);
      } catch (err) {
        console.error(err);
        setError("Server not responding");
      } finally {
        setLoading(false);
      }
    };

    fetchSchemes();
  }, [endpoint]);

  if (loading) {
    return <h3 className="text-center mt-5">Loading scholarships...</h3>;
  }

  if (error) {
    return <h3 className="text-center mt-5 text-danger">{error}</h3>;
  }

  return (
    <div className="container" style={{ paddingTop: "200px" }}>
      <h2
        className="mb-4 text-center"
        style={{
          fontFamily: "'Poppins', sans-serif",
          fontWeight: 600,
          letterSpacing: "1px",
          color: "#d31a1aff",
          textTransform: "uppercase",
        }}
      >
        Available Scholarship Schemes
      </h2>

      <div className="row">
        {schemes.map((scheme) => (
          <div className="col-md-4 mb-4" key={scheme.scholarship_id}>
            <div className="card shadow-sm h-100 border-0">
              <div className="card-body">
                <h5 className="card-title text-danger fw-bold">{scheme.title}</h5>
                <p className="card-text">{scheme.description}</p>
                <p>
                  <strong>Eligibility:</strong> {scheme.eligibility}
                </p>
                <p>
                  <strong>Deadline:</strong> {scheme.deadline}
                </p>
                <button className="btn btn-outline-danger w-100">
                  Apply Now
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
